import csv
import io

import pyotp

from app.config import USERS
from app.models import Reserva

RESERVA = {"sala": "Atlas", "fecha": "2026-10-05T10:00", "duracion_min": 60}


def _otp(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def _basic_auth(client, username, password, otp):
    return client.get(
        "/export",
        auth=(username, password),
        headers={"X-OTP": otp},
    )


def test_export_sin_reservas_devuelve_solo_cabecera(client):
    r = _basic_auth(client, "alice", "alice-pass", _otp("alice"))
    assert r.status_code == 200
    assert r.headers["content-type"] == "text/csv; charset=utf-8"
    filas = list(csv.reader(io.StringIO(r.text)))
    assert filas == [list(Reserva.model_fields)]


def test_export_con_reservas(client, auth):
    client.post("/reservas", json=RESERVA, headers=auth)
    r = _basic_auth(client, "alice", "alice-pass", _otp("alice"))
    assert r.status_code == 200
    filas = list(csv.reader(io.StringIO(r.text)))
    assert filas[0] == list(Reserva.model_fields)
    assert len(filas) == 2


def test_export_sin_credenciales(client):
    r = client.get("/export")
    assert r.status_code == 401


def test_export_con_password_incorrecta(client):
    r = _basic_auth(client, "alice", "mal", _otp("alice"))
    assert r.status_code == 401


def test_export_sin_otp(client):
    r = client.get("/export", auth=("alice", "alice-pass"))
    assert r.status_code == 401

